    public static function key(string $source):string{return'assignment_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array
    {
        $out=[];$en=explode('-',$locale,2)[0]==='en';
        foreach(self::ENGLISH as$source=>$translation)$out[self::key($source)]=$en?$translation:$source;
        return$out;
    }
    public static function text(string $source,array $messages):string
    {
        return$messages[self::key($source)]??TariffMessages::text($source,$messages);
    }
